function Empty({icon:Icon=Mail,title,detail,action}:{icon?:typeof Mail;title:string;detail:string;action?:ReactNode}){
 return <div className="empty"><Icon size={28}/><strong>{title}</strong><span>{detail}</span>{action}</div>;
}
function reflowEmailText(value:string){return (value||"").replace(/\r\n?/g,"\n").split(/\n\s*\n/).map(paragraph=>paragraph.replace(/\s*\n\s*/g," ").trim()).filter(Boolean).join("\n\n")}
function formatBytes(value:number){if(!Number.isFinite(value)||value<0)return "Unknown size";if(value<1024)return value+" B";if(value<1024*1024)return (value/1024).toFixed(1)+" KB";return (value/1024/1024).toFixed(1)+" MB"}
function EmailChips({label,values,onChange,placeholder}:{label:string;values:string[];onChange:(values:string[])=>void;placeholder?:string}){
 const [pending,setPending]=useState("");
 const commit=(raw:string)=>{const additions=raw.split(/[;,\n]+/).map(value=>value.trim()).filter(Boolean);if(additions.length){const seen=new Set(values.map(value=>value.toLowerCase()));onChange([...values,...additions.filter(value=>{const key=value.toLowerCase();if(seen.has(key))return false;seen.add(key);return true})])}setPending("")};
 return <div className="recipient-field"><label>{label}</label><div className="recipient-chip-input"><div className="recipient-chip-list">{values.map((address,index)=><span className="recipient-chip" key={address+"-"+index}><span>{address}</span><button type="button" title={"Remove "+address} aria-label={"Remove "+address} onMouseDown={event=>event.preventDefault()} onClick={()=>onChange(values.filter((_,i)=>i!==index))}><X size={12}/></button></span>)}</div><input className="recipient-chip-entry" type="text" value={pending} placeholder={values.length?"Add another address…":(placeholder||"Enter email address and press Enter")} onChange={event=>setPending(event.target.value)} onKeyDown={event=>{if(event.key==="Enter"||event.key===","||event.key===";"){event.preventDefault();commit(pending)}}} onBlur={()=>commit(pending)}/></div></div>;
}
function toLocalDateTime(value?:string|null){
 if(!value)return "";
 const date=new Date(value);
 if(Number.isNaN(date.getTime()))return "";
 const pad=(n:number)=>String(n).padStart(2,"0");
 return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}
function Login({onLogin}:{onLogin:(email:string,password:string)=>Promise<void>}){
 const [email,setEmail]=useState("");const [password,setPassword]=useState("");const [error,setError]=useState("");const [busy,setBusy]=useState(false);
 return <div className="login-page"><form className="login-card" onSubmit={async e=>{e.preventDefault();setBusy(true);setError("");try{await onLogin(email,password)}catch(err){setError(err instanceof Error?err.message:"Sign-in failed")}finally{setBusy(false)}}}>
  <div className="mark big">M</div><h1>Email Assistant</h1><p>Your private email workspace</p>
  <label>Email address</label><input type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} required/>
  <label>Password</label><input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required/>
  <button className="button primary full" disabled={busy}>{busy?"Signing in…":"Sign in"}</button>
  {error&&<div className="error">{error}</div>}<small className="secure-caption"><Lock size={13}/> Private single-user access</small>
 </form></div>;
}
